 c<-fread(file.path(out,'conflict_cluster_distribution.tsv'));c<-c[branch!='historical'&conflict_group=='BLCA_Fibroblast_HPCA_Epithelial'];ss<-fread(file.path(out,'cluster_domain_interpretation.tsv'));c<-merge(c,ss[,.(branch,cluster,interpretation)],by=c('branch','cluster'));c[,cluster_id:=paste(branch,cluster,sep=':')];p<-ggplot(c,aes(branch,n,fill=interpretation))+geom_col()+scale_fill_manual(values=co,name='Region interpretation')+jin_theme()+labs(x='Matched branch',y='Forward-conflict bins');export(p,'D1_conflict_region_composition',10,5.5,7)
